def act(observation,configuration):
 player=int(observation.get('player',0));step=min(int(observation.get('step',0)),719);action=copy.deepcopy(ACTIONS[step]);farms=observation.get('farms') or [];hands=(farms[player].get('hands') or []) if player<len(farms) else [];action['hands']=action.get('hands',[])[:len(hands)];return action
def agent(observation,configuration):return act(observation,configuration)
